final_submission.code:
size_t max_iterations = 100;
size_t iteration = 0;
bool inserted = false;

while (!inserted && iteration < max_iterations) {
    if (ckh_try_bucket_insert(ckh, argbucket, argkey, argdata)) {
        inserted = true;
    } else {
        // Evict and relocate elements
        size_t bucket = argbucket;
        const void *key = argkey;
        const void *data = argdata;
        while (bucket < ckh_bucket_count(ckh)) {
            ckhc_t *cell = &ckh->tab[ckh_cell_index(bucket, 0)];
            if (cell->key != NULL && ckh_keycomp(ckh, cell->key, key)) {
                // Swap cell with argkey and argdata
                std::swap(cell->key, (const void **)&argkey);
                std::swap(cell->data, (const void **)&argdata);
                bucket++;
            } else {
                break;
            }
        }
        iteration++;
    }
}

return !inserted;

